 void UpdateFixedList(int filter){using var profileScope=ViewingTableDiagnostics.Measure("ui.fixed-list");if(!preferences.LeftOpen)return;var failures=workspace.ViewingFailures;var items=workspace.ViewingTable.Items.OrderBy(i=>i.Z).Select(item=>(Item:item,Error:failures.FirstOrDefault(f=>f.StartsWith(ReferenceColorWorkspaceViewModel.ViewingFailurePrefix(item),StringComparison.Ordinal)))).Where(p=>filter==0||filter==1&&p.Error is not null||filter==2&&p.Error?.Contains("变化")==true).ToArray();var key=filter+"|selected="+string.Join(",",selection.Order())+"|"+string.Join("|",items.Select(p=>p.Item.VariantId+":"+p.Item.FrozenVariant.Name+":"+p.Error));if(key==fixedListKey&&fixedList.Children.Count==items.Length)return;fixedListKey=key;var wanted=items.Select(p=>p.Item.VariantId).ToHashSet();foreach(var id in fixedRows.Keys.Where(id=>!wanted.Contains(id)).ToArray()){fixedList.Children.Remove(fixedRows[id]);fixedRows.Remove(id);}for(int n=0;n<items.Length;n++){var pair=items[n];if(!fixedRows.TryGetValue(pair.Item.VariantId,out var button)){button=new Button{HorizontalContentAlignment=HorizontalAlignment.Left,Height=30,Padding=new(10,0,8,0),FontSize=11};button.Click+=(_,_)=>SelectItem((ViewingTableItem)button.Tag,false);fixedRows[pair.Item.VariantId]=button;}button.Background=selection.Contains(pair.Item.VariantId)?B("#30443E"):Brushes.Transparent;button.Tag=pair.Item;button.Content=pair.Item.FrozenVariant.Name;button.ToolTip=pair.Error??pair.Item.FrozenVariant.Name;if(fixedList.Children.IndexOf(button)!=n){fixedList.Children.Remove(button);fixedList.Children.Insert(n,button);}}}
 void WorkspaceChanged(object? sender,PropertyChangedEventArgs e)
 {using var profileScope=RAWSelectionAssistant.Services.ViewingTableDiagnostics.Measure("ui.notifications");
  if(closed)return;
  if(e.PropertyName==nameof(workspace.LastViewingFilmCompletion)){
   var done=workspace.LastViewingFilmCompletion;
   if(done is null){pendingCompletedVariant=null;return;}
   if(done.Revision>consumedCompletionRevision){consumedCompletionRevision=done.Revision;if(done.Pinned){pendingCompletedVariant=done.ResultId;selection.Clear();selection.Add(done.ResultId);selected=workspace.ViewingFrames.FirstOrDefault(f=>f.Item.VariantId==done.ResultId);}}
  }
  if(e.PropertyName==nameof(workspace.SessionPath)){pendingCompletedVariant=null;selection.Clear();selected=null;EndGesture(false);ExitDetail();InvalidateAvailability();}
  if(e.PropertyName==nameof(workspace.ActiveTarget))InvalidateAvailability();if(e.PropertyName==nameof(workspace.IsViewingLoading)){loadingBar.Visibility=workspace.IsViewingLoading?Visibility.Visible:Visibility.Collapsed;UpdateR55Chrome();}

  if(e.PropertyName==nameof(workspace.ViewingFrames)){
   UpdateCards();if(pendingCompletedVariant is Guid id){var result=workspace.ViewingFrames.FirstOrDefault(f=>f.Item.VariantId==id);if(result is not null){selected=result;pendingCompletedVariant=null;}}
   else if(selected is not null)selected=workspace.ViewingFrames.FirstOrDefault(f=>f.Item.VariantId==selected.Item.VariantId)??selected;
  }
  if(e.PropertyName is nameof(workspace.ViewingStatus) or nameof(workspace.ViewingFailures)){if(!transientFeedback)status.Text=DisplayViewingStatus();UpdateFixedList(fixedFilter);}
  if(e.PropertyName==nameof(workspace.ViewingTable)){ApplyViewport();UpdateCards();UpdateR55Light();UpdateFixedList(fixedFilter);UpdateContextPosition();}
  if(e.PropertyName is nameof(workspace.FilmTaskStatus) or nameof(workspace.IsFilmTaskRunning))UpdateFilmState();
  if(e.PropertyName is nameof(workspace.ViewingFrames) or nameof(workspace.ViewingFailures) or nameof(workspace.ViewingStatus) or nameof(workspace.LastViewingFilmCompletion) or nameof(workspace.SessionPath) or nameof(workspace.ActiveTarget))UpdateR55Chrome();
 }
 string FilmSourceDisplay(){if(selected is null)return "请选择照片";var completion=workspace.LastViewingFilmCompletion;if(completion?.ResultId==selected.Item.VariantId)return completion.FrozenSource.FrozenVariant.Name+"  →  "+selected.Item.FrozenVariant.Name;return selected.Item.FrozenVariant.Name;}
