 async Task PreflightAsync(){var revision=++availabilityRevision;availabilityCancellation?.Cancel();var cancel=new CancellationTokenSource();availabilityCancellation=cancel;preflightPending=true;generate.IsEnabled=false;filmReason.Text=workspace.IsFilmTaskRunning?workspace.FilmTaskStatus:"检查来源…";var frame=selected;try{var reason=frame is null?"请选择照片":await workspace.ViewingFilmAvailabilityAsync(frame.Item,cancel.Token);if(closed||revision!=availabilityRevision||cancel.IsCancellationRequested||selected?.Item.VariantId!=frame?.Item.VariantId)return;unavailable=reason;preflightVariant=frame?.Item.VariantId;filmReason.Text=workspace.IsFilmTaskRunning?workspace.FilmTaskStatus:reason??"已有8位创意胶片";generate.IsEnabled=reason is null&&!workspace.IsFilmTaskRunning;UpdateFilmState();}catch(Exception e)when(e is IOException or InvalidOperationException or NotSupportedException or OperationCanceledException or ArgumentException){if(!closed&&revision==availabilityRevision){unavailable=e.Message;filmReason.Text=e.Message;}}finally{if(revision==availabilityRevision){preflightPending=false;UpdateFilmState();}if(ReferenceEquals(availabilityCancellation,cancel))availabilityCancellation=null;cancel.Dispose();}}
 async void Generate(object sender,RoutedEventArgs e){generateWork=GenerateFromPanelAsync();await generateWork;}
 internal Task GenerateFromPanelAsync()=>GeneratePanelCoreAsync();
 async Task GeneratePanelCoreAsync(){var frame=selected;if(frame is null||preflightPending||unavailable is not null||preflightVariant!=frame.Item.VariantId)return;generate.IsEnabled=false;try{var choice=(PixelTartFilmProfile)filmChoice.SelectedItem;var settings=new PixelTartFilmSettings(true,choice.Id,filmAmount.Value,GrainAmount:filmGrain.Value);await workspace.GenerateViewingFilmAsync(frame.Item,filmId:choice.Id,requestedSettings:settings);if(!closed)await RefreshAsync();}catch(Exception error)when(error is IOException or InvalidOperationException or NotSupportedException or ArgumentException){if(!closed&&selected?.Item.VariantId==frame.Item.VariantId){filmReason.Text=error.Message;ShowFeedback(error.Message);}}}
 void ToggleLight(){workspace.SetViewingLight(!workspace.ViewingTable.PresentationLight);lampStarted=DateTime.UtcNow;if(!preferences.ReduceMotion&&SystemParameters.ClientAreaAnimation)lampTimer.Start();UpdateR55Light();}
 bool? previousLit;double previousBrightness=double.NaN,previousFlare=double.NaN;
 void UpdateR55Light(){var state=workspace.ViewingTable;var sample=LightResponse.Sample((DateTime.UtcNow-lampStarted).TotalSeconds,state.PresentationLight,preferences.ReduceMotion||!SystemParameters.ClientAreaAnimation);if(previousLit==state.PresentationLight&&previousBrightness==state.Brightness&&previousFlare==sample.Flare)return;bool lightChanged=previousLit!=state.PresentationLight;previousLit=state.PresentationLight;previousBrightness=state.Brightness;previousFlare=sample.Flare;board.Background=new SolidColorBrush(DisplayPanelColor(state.PresentationLight,state.Brightness,sample.Flare));board.Effect=state.PresentationLight?new DropShadowEffect{Color=Colors.White,BlurRadius=12,ShadowDepth=0,Opacity=.25+sample.Glow*.2}:null;if(lightChanged)foreach(var card in cardImageFrames.Values){card.Effect=state.PresentationLight?null:new DropShadowEffect{BlurRadius=3,ShadowDepth=1.5,Opacity=.16};}}
 // Versioned SDR board-only response: use pinned upstream PanelWhite at <=100%; use
 // remaining encoded display headroom above 100%. No photo/cache/export transform.
 internal static Color DisplayPanelColor(bool lit,double brightness,double flare=0){var basis=lit?Color.FromRgb(245,245,242):Color.FromRgb(227,217,191);var power=LightResponse.Power(brightness);var low=LightResponse.PanelWhite(power,0)/.9;var high=(LightResponse.PanelWhite(power,0)-.9)/(.948-.9);byte Channel(byte value){double result=power<=1?value*low:value+(255-value)*Math.Clamp(high,0,1)*.8;result+=(255-result)*Math.Clamp(flare,0,1)*.6;return(byte)Math.Clamp(Math.Round(result),0,255);}return Color.FromRgb(Channel(basis.R),Channel(basis.G),Channel(basis.B));}
 void OpenMore(){var menu=new ContextMenu();void Add(string text,Action action){var m=new MenuItem{Header=text};m.Click+=(_,_)=>action();menu.Items.Add(m);}Add("整理全局 Shift+Z",FitAll);Add("一键平铺…",()=>{if(MessageBox.Show(Window.GetWindow(this),"重新平铺所有照片？可撤销。","光镜",MessageBoxButton.OKCancel)==MessageBoxResult.OK)workspace.TileViewing();});Add("置于底层",()=>OrderSelection(false));Add("清空灯箱…",()=>{if(MessageBox.Show(Window.GetWindow(this),"移出全部照片？不删除源或变体，可撤销。","光镜",MessageBoxButton.OKCancel)==MessageBoxResult.OK)workspace.ClearViewingPlacements();});Add("撤销 Ctrl+Z",()=>workspace.UndoViewing());Add("重做 Ctrl+Y",()=>workspace.RedoViewing());Add("重新固定所选",()=>Run(async()=>{workspace.PinSelectedViewingVariants(true);await RefreshAsync();}));Add("减少动态效果",()=>{preferences=preferences with{ReduceMotion=!preferences.ReduceMotion};preferences.Save();});Add("关于观片台 / 开源许可",ShowLicense);menu.PlacementTarget=this;menu.IsOpen=true;}
 void ShowLicense(){var path=System.IO.Path.Combine(AppContext.BaseDirectory,"Licenses","LightTable-MIT.txt");MessageBox.Show(Window.GetWindow(this),"观片台功能部分基于 LightTable（观片台）\n原作者：抖音 @怕蛇LightTable · https://github.com/fuyuan9972-svg/LightTable\nWindows 移植：hqiy0831 · https://github.com/hqiy0831/LightTable-Windows\n经原作者许可在光镜中使用（非商业）。\n\n"+(System.IO.File.Exists(path)?System.IO.File.ReadAllText(path):"MIT License · Copyright (c) 2026 fuyuan9972-svg"),"光镜 · 开源许可");}
 internal double LeftSidebarWidth=>shell.ColumnDefinitions[0].Width.Value;internal double RightSidebarWidth=>shell.ColumnDefinitions[2].Width.Value;internal void OpenFilmSidebarForTest()=>OpenSidebar(true);internal void OpenInfoSidebarForTest()=>OpenSidebar(false);internal Task PreflightForTest()=>PreflightAsync();internal Task GenerateWork=>generateWork;internal void OpenLeftSidebarForTest(){preferences=preferences with{LeftOpen=true};preferences.Save();BuildSidebars();ApplySidebarWidths();}internal Button SidebarToggleButton=>sidebarToggle!;internal Button FilmCancelButton=>filmCancelButton!;internal bool CancelActionVisible=>filmCancelButton?.Visibility==Visibility.Visible;internal bool ResultActionsVisible=>resultActions.Visibility==Visibility.Visible;internal string AmountReadout=>amountReadout.Text;internal string GrainReadout=>grainReadout.Text;internal Rect ContextBounds=>new(contextBar.Margin.Left,contextBar.Margin.Top,Math.Max(208,contextBar.ActualWidth),24);internal Size CenterSize=>center.RenderSize;internal Button GenerateButton=>generate;internal Task CompareSelectedForHost()=>CompareAsync();internal Task ShowSelectedDetailForHost()=>ShowDetailAsync();internal void ExitDetailForHost()=>ExitDetail();internal bool GenerateEnabled=>generate.IsEnabled;internal void ToggleLampForTest()=>ToggleLight();internal void SetBrightnessForTest(double value)=>brightness.Value=value;internal void SelectForTest(ViewingFrame frame)=>SelectItem(frame.Item,false);internal Color BoardColor=>((SolidColorBrush)board.Background).Color;internal void FitAllForTest()=>FitAll();internal Guid? SelectedVariant=>selected?.Item.VariantId;internal string FilmSourceName=>filmSourceTitle.Text;internal string FilmPanelStatus=>filmReason.Text;internal bool FeedbackVisible=>status.Visibility==Visibility.Visible;internal int FixedFilter{get=>fixedFilter;set{fixedFilter=value;UpdateFixedList(value);}}
 internal void CloseSidebarForTest(){preferences=preferences with{RightOpen=false};BuildSidebars();ApplySidebarWidths();}
 string DisplayViewingStatus()=>workspace.ViewingFailures.Count>0?$"已载入 {workspace.ViewingFrames.Count} 张，{workspace.ViewingFailures.Count} 张失败":workspace.ViewingStatus;
 void ShowFeedback(string message){if(closed)return;status.Text=message;transientFeedback=true;status.Visibility=Visibility.Visible;feedbackTimer.Stop();feedbackTimer.Start();}
 void InvalidateAvailability(){availabilityRevision++;availabilityCancellation?.Cancel();preflightPending=false;preflightVariant=null;unavailable="请选择固定变体";generate.IsEnabled=false;}
 void UpdateFilmState(){bool running=workspace.IsFilmTaskRunning||workspace.FilmTaskStatus=="等待处理"||workspace.FilmTaskStatus=="取消中";bool hasTask=running||workspace.LastViewingFilmResult is not null||workspace.FilmTaskStatus.Contains("失败")||workspace.FilmTaskStatus.Contains("已取消");if(hasTask)filmReason.Text=workspace.FilmTaskStatus;else if(preflightPending)filmReason.Text="检查来源…";else filmReason.Text=unavailable??"已有8位创意胶片";generate.IsEnabled=!running&&unavailable is null&&!preflightPending&&selected is not null&&preflightVariant==selected.Item.VariantId;if(filmCancelButton is not null){filmCancelButton.Visibility=running?Visibility.Visible:Visibility.Collapsed;filmCancelButton.IsEnabled=workspace.FilmTaskStatus!="取消中";}resultActions.Visibility=!running&&workspace.LastViewingFilmResult is not null?Visibility.Visible:Visibility.Collapsed;}
 void StopR55(){fixedRows.Clear();DetachGestureOwner();feedbackTimer.Stop();slideshowRevision++;slideshow=false;workspace.PropertyChanged-=WorkspaceChanged;lampTimer.Stop();availabilityRevision++;availabilityCancellation?.Cancel();loupeImage.Source=null;sound?.Dispose();sound=null;}
}
